import { noop } from 'lodash-es';
import React, {
  PropsWithChildren,
  useCallback,
  useContext,
  useState,
} from 'react';

import { useValidateAndSanitize } from './useValidateAndSanitize.js';
import { NUMBER_SPIN_BUTTON_DEFAULTS } from '../constants.js';
import type { _NumberSpinButtonProps } from '../types.js';

type ContextType = {
  value: number | null;
  text: string;
  error: boolean;

  setError: React.Dispatch<React.SetStateAction<boolean>>;
  applyText: (
    value: string,
    element: HTMLSpanElement | null,
    fireOnChange?: boolean,
  ) => void;
  clearValue: (element: HTMLSpanElement | null, fireOnChange?: boolean) => void;

  smallStep: number;
  bigStep: number;
} & Required<
  Pick<_NumberSpinButtonProps, 'defaultValue' | 'minValue' | 'maxValue'>
>;

// Default context initialization
const Context = React.createContext<ContextType>({
  value: null,
  text: '',
  error: false,

  setError: noop,
  applyText: noop,
  clearValue: noop,

  defaultValue: 0,
  minValue: 0,
  maxValue: 0,

  bigStep: 0,
  smallStep: 0,
});

/**
 * Provides access to the spinbutton context.
 */
export const useNumberSpinButtonContext = () => {
  return useContext(Context);
};

/**
 * Holds the inner component state and provides functions to modify it.
 */
export const NumberSpinButtonContextProvider = ({
  children,
  ...props
}: PropsWithChildren<_NumberSpinButtonProps>) => {
  // set defaults
  const {
    defaultValue = NUMBER_SPIN_BUTTON_DEFAULTS.VALUE,
    minValue = NUMBER_SPIN_BUTTON_DEFAULTS.MIN_VALUE,
    maxValue = NUMBER_SPIN_BUTTON_DEFAULTS.MAX_VALUE,
    onChange,
  } = props;

  // Component states
  const [value, setValue] = useState(defaultValue);
  const [text, setText] = useState('');
  const [error, setError] = useState(false);
  const { parse, format } = useValidateAndSanitize(props);

  // Callback to update the inner component state and a given dom element if provided.
  const applyText = useCallback(
    (text: string, element: HTMLSpanElement | null, fireOnChange = false) => {
      const newValue = parse(text);
      setText(text);
      setValue(newValue);

      if (element) {
        element.textContent = format(text);
      }

      fireOnChange && onChange?.(newValue);
    },
    [format, onChange, parse],
  );

  // Callback to clear the inner component state and a given dom element if provided.
  const clearValue = useCallback(
    (element: HTMLSpanElement | null, fireOnChange = false) => {
      setValue(null);
      setText('');
      if (element) {
        element.textContent = '';
      }
      fireOnChange && onChange?.(null);
    },
    [onChange],
  );

  return (
    <Context.Provider
      value={{
        value,
        text,
        error,
        setError,
        applyText,
        clearValue,
        defaultValue,
        minValue,
        maxValue,
        smallStep: NUMBER_SPIN_BUTTON_DEFAULTS.SMALL_STEP,
        bigStep: NUMBER_SPIN_BUTTON_DEFAULTS.BIG_STEP,
      }}
    >
      {children}
    </Context.Provider>
  );
};
